const all = $input.all().map(i => i.json);
const batchSize = $('Globals').first().json.BATCH_SIZE || 1;
const pending = all.filter(r => r.status === 'pending');
if (pending.length === 0) {
  return [{ json: { _empty: true } }];
}
const batch = pending.slice(0, batchSize);
return batch.map(r => ({ json: r }));

const raw = $json.text || $json.data || '';
let pages = [];
if (Array.isArray(raw)) pages = raw;
else if (typeof raw === 'string') {
  pages = raw.split('\f');
  if (pages.length < 3) pages = raw.split(/\n\s*\n\s*\n/);
}
// Cap to 30k chars to stay friendly with the model context
const paperText = pages.join('\n\n').slice(0, 30000);
const ctx = $('Loop Over Papers').item.json;
return [{ json: { ...ctx, paper_text: paperText, paper_total_pages: pages.length } }];

// ============================================================================
//  Parse Concept  —  paste the WHOLE file into the "Parse Concept" Code node
//  (mode: Run Once for All Items).
//
//  Two classes of problem, handled differently:
//
//   HARD FAIL (throw)   structural damage nothing downstream can survive:
//                       unparseable JSON, no slides, wrong slide count,
//                       missing hook/cta anchors, a slide with no headline.
//
//   SOFT REPAIR (warn)  everything a deterministic fix can rescue: an over-long
//                       string, one item too many, an unknown icon, a slide over
//                       its density budget. These are repaired, recorded in
//                       _warnings, and written to the sheet's notes column so
//                       the human reviewer knows exactly what to eyeball.
//
//  The point of the split: a single greedy adjective should never cost you a
//  Sonnet call and a render.
// ============================================================================

// ---------------------------------------------------------------------------
//  CONFIG  —  keep in sync with the agent prompt and Build Carousel HTML
// ---------------------------------------------------------------------------
const MIN_SLIDES = 5;
const MAX_SLIDES = 10;

const SLIDE_TYPES = ['hook', 'stakes', 'setup', 'concept', 'payoff', 'relevance', 'cta'];

// Per-slide density budget. hook/stakes/cta render at a much larger type size,
// so they get less room for structure.
const BUDGET = { hook: 4, stakes: 6, cta: 5, setup: 8, concept: 8, payoff: 8, relevance: 8 };
const BUDGET_DEFAULT = 8;

const ICONS = [
  'alert','info','question','check','check-circle','x','x-circle','lightbulb','brain',
  'users','user','clock','calendar','chart-bar','trending-up','trending-down','percent',
  'target','search','flask','book','file-text','clipboard','message','quote','eye',
  'eye-off','heart','zap','scale','lock','shield','layers','refresh','globe',
  'arrow-right','home',
];
const ICON_FALLBACK = 'info';

// Character budgets. These are the numbers the layout was designed against;
// going over does not crash anything, it just makes a slide look cramped.
const LIMITS = {
  kicker: 26, headline: 95, accent: 24,   // headline is a BACKSTOP: autofit handles overflow
  paragraph: 230,
  stat_value: 12, stat_label: 52, stat_sub: 95,
  card_title: 30, card_body: 95,
  rule_title: 34, rule_body: 135,
  num_title: 34, num_sub: 62,
  step_title: 30, step_sub: 58,
  tl_label: 16, tl_body: 135,
  cmp_title: 30, cmp_body: 125,
  quote_text: 190, quote_attr: 62,
};

// type -> { min, max } items for the list-shaped blocks
const ITEM_RANGE = {
  cards: [2, 3], rule_blocks: [2, 3], numbered_list: [3, 4],
  steps: [3, 4], timeline: [3, 4],
};

const BLOCK_TYPES = ['paragraph','stat','cards','rule_blocks','numbered_list','steps','timeline','compare','quote'];

// ---------------------------------------------------------------------------
//  HELPERS
// ---------------------------------------------------------------------------
const warnings = [];
const warn = (m) => { if (warnings.length < 40) warnings.push(m); };

// The TU/e house rule bans em and en dashes. Rather than failing a whole run
// over a punctuation slip, normalise them: " — " becomes ", ".
function dedash(s, where) {
  const str = String(s == null ? '' : s);
  if (!/[\u2014\u2013]/.test(str)) return str;
  warn(`dash normalised in ${where}`);
  return str
    .replace(/\s*[\u2014\u2013]\s*$/g, '')
    .replace(/\s*[\u2014\u2013]\s*/g, ', ')
    .replace(/,\s*,/g, ',');
}

// Words that must never be the last word of a truncated string. "...studies at"
// reads as a bug; "...studies" reads as an edit.
const DANGLING = new Set(['a','an','the','and','or','but','of','to','in','on','at','by','for',
  'with','from','as','is','are','was','were','that','this','it','its','our','we','their','than',
  'then','so','if','into','over','about','after','before','when','while','not','no','one','two',
  'more','most','very','just','also','only','up','out','can','has','have','how','why','what']);

// Truncate on a word boundary, then walk back over any trailing function words
// so the result still reads as a finished phrase. `ellipsis: false` for
// headlines, where a trailing "..." always looks like a defect.
function clamp(s, max, where, ellipsis = true) {
  const str = String(s == null ? '' : s).trim();
  if (str.length <= max) return str;
  warn(`${where} truncated (${str.length} > ${max})`);

  const budget = ellipsis ? max - 1 : max;
  const landedOnSpace = /\s/.test(str.charAt(budget));
  const words = str.slice(0, budget).split(/\s+/).filter(Boolean);
  // If the cut fell inside a word, that word is incomplete: drop it.
  if (!landedOnSpace && words.length > 1) words.pop();
  while (words.length > 1) {
    const last = words[words.length - 1].toLowerCase().replace(/[^a-z0-9']/g, '');
    if (!DANGLING.has(last)) break;
    words.pop();
  }
  let out = words.join(' ').replace(/[,;:.\u2026\s]+$/, '');
  if (!out) out = str.slice(0, budget);
  return ellipsis ? out + '\u2026' : out;
}

// dedash + clamp in one call — every string that reaches the renderer goes
// through this, so there is exactly one place text can be malformed.
const txt = (s, max, where, ellipsis = true) => clamp(dedash(s, where), max, where, ellipsis);

const isObj = (v) => v && typeof v === 'object' && !Array.isArray(v);

// A headline wraps at roughly 24 characters per line (18 on the oversized hook
// type). The budgets assume a two line headline, so every line past the second
// costs one density point, exactly like any other 80px of vertical space.
function headlineWeight(headline, slideType) {
  const perLine = slideType === 'hook' ? 18 : (slideType === 'stakes' ? 21 : 24);
  return Math.max(0, Math.ceil(String(headline || '').length / perLine) - 2);
}

function blockWeight(b) {
  const n = Array.isArray(b.items) ? b.items.length : 0;
  switch (b.type) {
    case 'paragraph':     return String(b.text || '').length > 130 ? 2 : 1;
    case 'quote':         return b.attribution ? 3 : 2;
    case 'stat':          return 3;
    case 'cards':         return 2 * n;
    case 'rule_blocks':   return 2 * n;
    case 'numbered_list': return 1 + n;
    case 'steps':         return 2 + n;
    case 'timeline':      return 1 + 2 * n;
    case 'compare':       return 5;
    case 'figure':        return 4;
    default:              return 1;
  }
}

// Trim a list block to its allowed length.
function clampItems(block, where) {
  const range = ITEM_RANGE[block.type];
  if (!range) return true;
  if (!Array.isArray(block.items)) return false;
  const [min, max] = range;
  if (block.items.length < min) {
    warn(`${where}: ${block.type} had ${block.items.length} items (min ${min}), block dropped`);
    return false;
  }
  if (block.items.length > max) {
    warn(`${where}: ${block.type} trimmed from ${block.items.length} to ${max} items`);
    block.items = block.items.slice(0, max);
  }
  return true;
}

function normIcon(name, where) {
  if (!name) return undefined;
  const k = String(name).trim().toLowerCase();
  if (ICONS.includes(k)) return k;
  warn(`${where}: unknown icon "${name}" replaced with "${ICON_FALLBACK}"`);
  return ICON_FALLBACK;
}

// ---------------------------------------------------------------------------
//  BLOCK NORMALISERS  —  return a clean block, or null to drop it.
// ---------------------------------------------------------------------------
function normBlock(raw, where) {
  if (!isObj(raw) || !raw.type) { warn(`${where}: malformed block dropped`); return null; }
  const type = String(raw.type).trim();

  if (!BLOCK_TYPES.includes(type)) {
    warn(`${where}: unknown block type "${type}" dropped`);
    return null;
  }

  switch (type) {
    case 'paragraph': {
      const text = txt(raw.text, LIMITS.paragraph, `${where}/paragraph`);
      if (!text) { warn(`${where}: empty paragraph dropped`); return null; }
      return { type, text };
    }

    case 'stat': {
      const value = txt(raw.value, LIMITS.stat_value, `${where}/stat.value`);
      const label = txt(raw.label, LIMITS.stat_label, `${where}/stat.label`);
      if (!value || !label) { warn(`${where}: incomplete stat dropped`); return null; }
      const out = { type, value, label };
      if (raw.sub) out.sub = txt(raw.sub, LIMITS.stat_sub, `${where}/stat.sub`);
      return out;
    }

    case 'quote': {
      const text = txt(raw.text, LIMITS.quote_text, `${where}/quote`);
      if (!text) { warn(`${where}: empty quote dropped`); return null; }
      const out = { type, text };
      if (raw.attribution) out.attribution = txt(raw.attribution, LIMITS.quote_attr, `${where}/quote.attr`);
      return out;
    }

    case 'compare': {
      if (!isObj(raw.bad) || !isObj(raw.good)) { warn(`${where}: incomplete compare dropped`); return null; }
      return {
        type,
        bad:  { title: txt(raw.bad.title,  LIMITS.cmp_title, `${where}/compare.bad.title`),
                body:  txt(raw.bad.body,   LIMITS.cmp_body,  `${where}/compare.bad.body`) },
        good: { title: txt(raw.good.title, LIMITS.cmp_title, `${where}/compare.good.title`),
                body:  txt(raw.good.body,  LIMITS.cmp_body,  `${where}/compare.good.body`) },
      };
    }

    case 'cards': {
      const b = { type, items: Array.isArray(raw.items) ? raw.items.slice() : [] };
      if (!clampItems(b, where)) return null;
      b.items = b.items.filter(isObj).map((it, i) => {
        const o = {
          title: txt(it.title, LIMITS.card_title, `${where}/card${i + 1}.title`),
          body:  txt(it.body,  LIMITS.card_body,  `${where}/card${i + 1}.body`),
        };
        const ic = normIcon(it.icon, `${where}/card${i + 1}`);
        if (ic) o.icon = ic;
        return o;
      }).filter((it) => it.title);
      return b.items.length >= ITEM_RANGE.cards[0] ? b : null;
    }

    case 'rule_blocks': {
      const b = { type, items: Array.isArray(raw.items) ? raw.items.slice() : [] };
      if (!clampItems(b, where)) return null;
      b.items = b.items.filter(isObj).map((it, i) => ({
        title: txt(it.title, LIMITS.rule_title, `${where}/rule${i + 1}.title`),
        body:  txt(it.body,  LIMITS.rule_body,  `${where}/rule${i + 1}.body`),
      })).filter((it) => it.title);
      return b.items.length >= ITEM_RANGE.rule_blocks[0] ? b : null;
    }

    case 'numbered_list': {
      const b = { type, items: Array.isArray(raw.items) ? raw.items.slice() : [] };
      if (!clampItems(b, where)) return null;
      b.items = b.items.filter(isObj).map((it, i) => ({
        title: txt(it.title, LIMITS.num_title, `${where}/item${i + 1}.title`),
        sub:   txt(it.sub,   LIMITS.num_sub,   `${where}/item${i + 1}.sub`),
      })).filter((it) => it.title);
      return b.items.length >= ITEM_RANGE.numbered_list[0] ? b : null;
    }

    case 'steps': {
      const b = { type, items: Array.isArray(raw.items) ? raw.items.slice() : [] };
      if (!clampItems(b, where)) return null;
      b.items = b.items.filter(isObj).map((it, i) => ({
        title: txt(it.title, LIMITS.step_title, `${where}/step${i + 1}.title`),
        sub:   txt(it.sub,   LIMITS.step_sub,   `${where}/step${i + 1}.sub`),
      })).filter((it) => it.title);
      return b.items.length >= ITEM_RANGE.steps[0] ? b : null;
    }

    case 'timeline': {
      const b = { type, items: Array.isArray(raw.items) ? raw.items.slice() : [] };
      if (!clampItems(b, where)) return null;
      b.items = b.items.filter(isObj).map((it, i) => ({
        label: txt(it.label, LIMITS.tl_label, `${where}/tl${i + 1}.label`),
        body:  txt(it.body,  LIMITS.tl_body,  `${where}/tl${i + 1}.body`),
      })).filter((it) => it.label);
      return b.items.length >= ITEM_RANGE.timeline[0] ? b : null;
    }
  }
  return null;
}

// ---------------------------------------------------------------------------
//  PARSE
// ---------------------------------------------------------------------------
const raw = $json.output || '';
const cleaned = String(raw)
  .replace(/^\s*```(?:json)?\s*/i, '')
  .replace(/```\s*$/i, '')
  .trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  // Last-ditch: grab the outermost {...} in case the model wrapped it in prose.
  const m = cleaned.match(/\{[\s\S]*\}/);
  if (!m) throw new Error('Carousel concept invalid JSON: ' + e.message + ' | raw: ' + cleaned.slice(0, 400));
  try { parsed = JSON.parse(m[0]); }
  catch (e2) { throw new Error('Carousel concept invalid JSON: ' + e2.message + ' | raw: ' + cleaned.slice(0, 400)); }
}

// ---------------------------------------------------------------------------
//  HARD STRUCTURAL CHECKS
// ---------------------------------------------------------------------------
const slidesIn = Array.isArray(parsed.slides) ? parsed.slides : [];
if (slidesIn.length < MIN_SLIDES || slidesIn.length > MAX_SLIDES) {
  throw new Error(`Expected ${MIN_SLIDES}-${MAX_SLIDES} slides, got ${slidesIn.length}`);
}
if (slidesIn[0]?.slide_type !== 'hook' || slidesIn[slidesIn.length - 1]?.slide_type !== 'cta') {
  throw new Error(`First slide must be "hook" and last must be "cta" (got "${slidesIn[0]?.slide_type}" ... "${slidesIn[slidesIn.length - 1]?.slide_type}")`);
}

// ---------------------------------------------------------------------------
//  NORMALISE EACH SLIDE
// ---------------------------------------------------------------------------
const normalized = slidesIn.map((s, i) => {
  const n = i + 1;
  const where = `slide ${n}`;

  let slide_type = String(s.slide_type || '').trim();
  if (!SLIDE_TYPES.includes(slide_type)) {
    warn(`${where}: unknown slide_type "${slide_type}" treated as "concept"`);
    slide_type = 'concept';
  }

  const headline = txt(s.headline, LIMITS.headline, `${where}.headline`, false);
  if (!headline) throw new Error(`${where} has no headline`);

  const kicker = s.kicker ? txt(s.kicker, LIMITS.kicker, `${where}.kicker`).toUpperCase() : '';

  // accent must appear verbatim in the headline, otherwise the highlight is a
  // silent no-op and the model is being sloppy — better to know.
  let accent = s.accent ? dedash(s.accent, `${where}.accent`).trim().slice(0, LIMITS.accent) : '';
  if (accent && !headline.toLowerCase().includes(accent.toLowerCase())) {
    warn(`${where}: accent "${accent}" not found in headline, dropped`);
    accent = '';
  }

  // Blocks. Accept a legacy plain "body" string so an older concept payload
  // still renders instead of coming out blank.
  let rawBlocks = Array.isArray(s.blocks) ? s.blocks : [];
  if (!rawBlocks.length && s.body) {
    warn(`${where}: legacy "body" field converted to a paragraph block`);
    rawBlocks = [{ type: 'paragraph', text: s.body }];
  }

  let blocks = rawBlocks.map((b) => normBlock(b, where)).filter(Boolean);

  // Density budget. When a slide is too tall, sacrifice the last paragraph
  // before touching anything structural — the paragraph is nearly always
  // connective tissue, the structured block is the reason the slide exists.
  // Only once no paragraphs remain do we drop from the end.
  const budget = BUDGET[slide_type] ?? BUDGET_DEFAULT;
  const hw = headlineWeight(headline, slide_type);
  if (hw) warn(`${where}: headline wraps to ${hw + 2} lines, costs ${hw} of the density budget`);
  let weight = blocks.reduce((sum, b) => sum + blockWeight(b), hw);
  while (weight > budget && blocks.length > 1) {
    let idx = -1;
    for (let k = blocks.length - 1; k >= 0; k--) {
      if (blocks[k].type === 'paragraph') { idx = k; break; }
    }
    if (idx === -1) idx = blocks.length - 1;
    const [dropped] = blocks.splice(idx, 1);
    weight -= blockWeight(dropped);
    warn(`${where}: over density budget (${budget}), dropped "${dropped.type}" block`);
  }
  if (weight > budget) warn(`${where}: single block still over budget (${weight}/${budget}), check the render`);

  return { slide_number: n, slide_type, kicker, headline, accent, blocks, density: weight };
});

// A carousel of nothing but headlines means the block plumbing is broken
// upstream — that is worth failing loudly on.
if (!normalized.some((s) => s.blocks.length > 0)) {
  throw new Error('No slide produced a single valid block. Check the agent prompt output shape.');
}

// ---------------------------------------------------------------------------
//  CAPTION + HASHTAGS
// ---------------------------------------------------------------------------
const caption = dedash(parsed.caption || '', 'caption').trim();
if (caption.split(/\s+/).filter(Boolean).length < 100) warn('caption is shorter than 100 words');

const hashtags = (Array.isArray(parsed.hashtags) ? parsed.hashtags : [])
  .map((h) => String(h).trim().toLowerCase())
  .map((h) => (h.startsWith('#') ? h : '#' + h))
  .filter((h) => /^#[a-z0-9]+$/.test(h))
  .slice(0, 7);
if (hashtags.length < 4) warn(`only ${hashtags.length} valid hashtags`);

// ---------------------------------------------------------------------------
//  OUTPUT
// ---------------------------------------------------------------------------
const ctx = $('Build Paper Text').item.json;

return [{
  json: {
    drive_file_id: ctx.drive_file_id,
    drive_file_name: ctx.drive_file_name,
    title: ctx.title,
    authors: ctx.authors,
    field: ctx.field,
    content_hook: dedash(parsed.content_hook || '', 'content_hook'),
    content_brief: dedash(parsed.content_brief || '', 'content_brief'),
    slides: normalized,
    caption,
    hashtags,
    total_slides: normalized.length,
    _warnings: warnings,
    _block_summary: normalized
      .map((s) => `${s.slide_number}:${s.slide_type}[${s.blocks.map((b) => b.type).join(',') || 'none'}] d=${s.density}`)
      .join(' | '),
  },
}];

// ============================================================================
//  Build Carousel HTML  —  paste the WHOLE file into the "Build Carousel HTML"
//  Code node (mode: Run Once for All Items).
//
//  Replaces the old headline+body renderer with a BLOCK RENDERER.
//  A slide is now: kicker (chip) + headline + an ordered array of blocks.
//  The model composes blocks; this file owns 100% of the markup and styling,
//  so the brand can never drift.
//
//  Everything above the "n8n GLUE" marker is portable plain JS with no n8n
//  dependencies — tools/make-preview.js reuses it to render a local preview.
// ============================================================================

// ---------------------------------------------------------------------------
//  1. ICONS  —  inline SVG, 24x24, stroke = currentColor so every icon
//     automatically inherits the slide palette. Keep this list in sync with
//     ICONS in the Parse Concept node and with the prompt's icon menu.
// ---------------------------------------------------------------------------
const ICON_PATHS = {
  alert:        '<path d="M12 3.2 21.6 20H2.4Z"/><line x1="12" y1="9.5" x2="12" y2="14"/><circle cx="12" cy="17.2" r=".9" fill="currentColor" stroke="none"/>',
  info:         '<circle cx="12" cy="12" r="9"/><line x1="12" y1="11" x2="12" y2="17"/><circle cx="12" cy="7.6" r=".9" fill="currentColor" stroke="none"/>',
  question:     '<circle cx="12" cy="12" r="9"/><path d="M9.3 9.4a2.8 2.8 0 1 1 3.5 2.7c-.6.2-.8.7-.8 1.3v.5"/><circle cx="12" cy="16.8" r=".9" fill="currentColor" stroke="none"/>',
  check:        '<polyline points="4 12.5 9.5 18 20 6.5"/>',
  'check-circle': '<circle cx="12" cy="12" r="9"/><polyline points="7.8 12.2 10.8 15.2 16.2 8.8"/>',
  x:            '<line x1="5.5" y1="5.5" x2="18.5" y2="18.5"/><line x1="18.5" y1="5.5" x2="5.5" y2="18.5"/>',
  'x-circle':   '<circle cx="12" cy="12" r="9"/><line x1="9" y1="9" x2="15" y2="15"/><line x1="15" y1="9" x2="9" y2="15"/>',
  lightbulb:    '<path d="M9.2 17.2h5.6"/><path d="M10.2 20.6h3.6"/><path d="M12 3.2a5.9 5.9 0 0 0-3.5 10.7c.5.4.8 1 .9 1.6h5.2c.1-.6.4-1.2.9-1.6A5.9 5.9 0 0 0 12 3.2Z"/>',
  brain:        '<path d="M12 5.6v13"/><path d="M12 6.6A3.4 3.4 0 0 0 5.7 8.2 3 3 0 0 0 4.3 13a3.4 3.4 0 0 0 2.9 3.3A3 3 0 0 0 12 18"/><path d="M12 6.6a3.4 3.4 0 0 1 6.3 1.6 3 3 0 0 1 1.4 4.8 3.4 3.4 0 0 1-2.9 3.3A3 3 0 0 1 12 18"/>',
  users:        '<circle cx="9" cy="8" r="3.2"/><path d="M3.2 19.8a5.8 5.8 0 0 1 11.6 0"/><path d="M16.4 5.5a3.2 3.2 0 0 1 0 5"/><path d="M16.9 14.3a5.8 5.8 0 0 1 3.9 5.5"/>',
  user:         '<circle cx="12" cy="8" r="3.4"/><path d="M5.2 20a6.8 6.8 0 0 1 13.6 0"/>',
  clock:        '<circle cx="12" cy="12" r="9"/><polyline points="12 6.8 12 12.2 16 14.2"/>',
  calendar:     '<rect x="3.2" y="5.2" width="17.6" height="15.6" rx="2"/><line x1="3.2" y1="10" x2="20.8" y2="10"/><line x1="8" y1="3.2" x2="8" y2="7"/><line x1="16" y1="3.2" x2="16" y2="7"/>',
  'chart-bar':  '<line x1="3.2" y1="20.6" x2="20.8" y2="20.6"/><rect x="5" y="11.5" width="3.8" height="9.1"/><rect x="10.1" y="6.5" width="3.8" height="14.1"/><rect x="15.2" y="14.5" width="3.8" height="6.1"/>',
  'trending-up':'<polyline points="3.2 17 9 11.2 13 15.2 20.8 6.6"/><polyline points="15.2 6.6 20.8 6.6 20.8 12"/>',
  'trending-down':'<polyline points="3.2 7 9 12.8 13 8.8 20.8 17.4"/><polyline points="15.2 17.4 20.8 17.4 20.8 12"/>',
  percent:      '<line x1="19" y1="5" x2="5" y2="19"/><circle cx="7.8" cy="7.8" r="2.6"/><circle cx="16.2" cy="16.2" r="2.6"/>',
  target:       '<circle cx="12" cy="12" r="8.8"/><circle cx="12" cy="12" r="4.8"/><circle cx="12" cy="12" r="1.4" fill="currentColor" stroke="none"/>',
  search:       '<circle cx="10.8" cy="10.8" r="6.4"/><line x1="15.6" y1="15.6" x2="20.6" y2="20.6"/>',
  flask:        '<path d="M10 3.4v6L4.7 17.9A2 2 0 0 0 6.4 21h11.2a2 2 0 0 0 1.7-3.1L14 9.4v-6"/><line x1="8.8" y1="3.4" x2="15.2" y2="3.4"/><line x1="7.3" y1="14.8" x2="16.7" y2="14.8"/>',
