const ICON_FALLBACK = 'info';

function icon(name, cls) {
  const key = ICON_PATHS[name] ? name : ICON_FALLBACK;
  return '<svg class="' + (cls || 'ico') + '" viewBox="0 0 24 24" fill="none" stroke="currentColor" ' +
         'stroke-width="1.85" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' +
         ICON_PATHS[key] + '</svg>';
}

// ---------------------------------------------------------------------------
//  2. TEXT HELPERS
// ---------------------------------------------------------------------------
const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// Escape first, then apply the tiny inline markdown subset the model is allowed
// to use: **bold** and *italic*. Nothing else is honoured, so the model can
// never inject markup.
function inline(s) {
  return esc(s)
    .replace(/\*\*([^*]+)\*\*/g, '<b>$1</b>')
    .replace(/(^|[^*])\*([^*]+)\*/g, '$1<i>$2</i>');
}

// Headline: inline markdown plus the single "accent" highlight, matched
// case-insensitively on the first occurrence.
function headlineHtml(text, accent) {
  const html = inline(text);
  if (!accent) return html;
  const needle = esc(accent);
  const idx = html.toLowerCase().indexOf(needle.toLowerCase());
  if (idx === -1) return html;
  return html.slice(0, idx) +
         '<span class="accent">' + html.slice(idx, idx + needle.length) + '</span>' +
         html.slice(idx + needle.length);
}

// ---------------------------------------------------------------------------
//  3. DENSITY MODEL  —  identical weights to the Parse Concept node.
//     Used here only to decide vertical alignment (dense slides top-align,
//     airy slides centre), never to reject anything. Parse Concept is the
//     single place that enforces the budget.
// ---------------------------------------------------------------------------
function blockWeight(b) {
  const n = Array.isArray(b.items) ? b.items.length : 0;
  switch (b.type) {
    case 'paragraph':     return String(b.text || '').length > 130 ? 2 : 1;
    case 'quote':         return b.attribution ? 3 : 2;
    case 'stat':          return 3;
    case 'cards':         return 2 * n;
    case 'rule_blocks':   return 2 * n;
    case 'numbered_list': return 1 + n;
    case 'steps':         return 2 + n;
    case 'timeline':      return 1 + 2 * n;
    case 'compare':       return 5;
    case 'figure':        return 4;
    default:              return 1;
  }
}
// Mirror of headlineWeight() in Parse Concept: extra wrapped headline lines are
// real vertical space and count against the same budget.
function headlineWeight(headline, slideType) {
  const perLine = slideType === 'hook' ? 18 : (slideType === 'stakes' ? 21 : 24);
  return Math.max(0, Math.ceil(String(headline || '').length / perLine) - 2);
}
const slideWeight = (blocks, headline, slideType) =>
  (blocks || []).reduce((sum, b) => sum + blockWeight(b), headlineWeight(headline, slideType));

// ---------------------------------------------------------------------------
//  4. BLOCK RENDERERS  —  one pure function per block type.
//     To add a new block: write a function, register it in RENDERERS, add a
//     weight above, add the CSS, add it to the parser allowlist and the prompt.
// ---------------------------------------------------------------------------
const RENDERERS = {

  paragraph: (b) => `<p class="b-para">${inline(b.text)}</p>`,

  stat: (b) => `
    <div class="b-stat">
      <div class="stat-value">${inline(b.value)}</div>
      <div class="stat-label">${inline(b.label)}</div>
      ${b.sub ? `<div class="stat-sub">${inline(b.sub)}</div>` : ''}
    </div>`,

  cards: (b) => `
    <div class="b-cards">
      ${b.items.map((it) => `
      <div class="card">
        <div class="card-head">
          ${it.icon ? `<span class="card-ico">${icon(it.icon)}</span>` : ''}
          <span class="card-title">${inline(it.title)}</span>
        </div>
        ${it.body ? `<p class="card-body">${inline(it.body)}</p>` : ''}
      </div>`).join('')}
    </div>`,

  rule_blocks: (b) => `
    <div class="b-rules">
      ${b.items.map((it) => `
      <div class="rule">
        <div class="rule-title">${inline(it.title)}</div>
        <p class="rule-body">${inline(it.body)}</p>
      </div>`).join('')}
    </div>`,

  numbered_list: (b) => `
    <div class="b-numlist">
      ${b.items.map((it, i) => `
      <div class="numrow">
        <div class="numrow-n">${i + 1}</div>
        <div class="numrow-txt">
          <div class="numrow-title">${inline(it.title)}</div>
          ${it.sub ? `<div class="numrow-sub">${inline(it.sub)}</div>` : ''}
        </div>
      </div>`).join('')}
    </div>`,

  steps: (b) => `
    <div class="b-steps">
      ${b.items.map((it, i) => `
      <div class="step">
        <div class="step-n">${i + 1}</div>
        <div class="step-txt">
          <div class="step-title">${inline(it.title)}</div>
          ${it.sub ? `<div class="step-sub">${inline(it.sub)}</div>` : ''}
        </div>
      </div>`).join('')}
    </div>`,

  timeline: (b) => `
    <div class="b-timeline">
      ${b.items.map((it, i) => `
      <div class="tl${i === b.items.length - 1 ? ' tl--last' : ''}">
        <div class="tl-n">${i + 1}</div>
        <div class="tl-txt">
          <div class="tl-label">${inline(it.label)}</div>
          <p class="tl-body">${inline(it.body)}</p>
        </div>
      </div>`).join('')}
    </div>`,

  compare: (b) => `
    <div class="b-compare">
      <div class="cmp cmp--bad">
        <div class="cmp-head">${icon('x-circle', 'ico cmp-ico')}<span>${inline(b.bad.title)}</span></div>
        <p class="cmp-body">${inline(b.bad.body)}</p>
      </div>
      <div class="cmp cmp--good">
        <div class="cmp-head">${icon('check-circle', 'ico cmp-ico')}<span>${inline(b.good.title)}</span></div>
        <p class="cmp-body">${inline(b.good.body)}</p>
      </div>
    </div>`,

  quote: (b) => `
    <blockquote class="b-quote">
      <p class="quote-text">${inline(b.text)}</p>
      ${b.attribution ? `<div class="quote-attr">${inline(b.attribution)}</div>` : ''}
    </blockquote>`,

  // Reserved for the PDF-figure / AI-hero work. Not on the model's menu yet,
  // but rendering already works if a block is injected downstream.
  figure: (b) => `
    <figure class="b-figure">
      <img src="${esc(b.src)}" alt="">
      ${b.caption ? `<figcaption>${inline(b.caption)}</figcaption>` : ''}
    </figure>`,
};

function renderBlock(b) {
  const fn = RENDERERS[b && b.type];
  return fn ? fn(b) : '';
}

