    -webkit-font-smoothing:antialiased;
  }

  /* .content is the fixed measuring frame; .fit is the thing that shrinks.
     zoom (not transform:scale) because zoom reflows text properly in Chromium,
     so a shrunk slide rewraps instead of just getting smaller.             */
  .content { flex:1; min-height:0; display:flex; flex-direction:column;
