  b { font-weight:700; color:var(--fg); }
  i { font-style:italic; }
  .ico { width:100%; height:100%; }

  /* ---- paragraph ---- */
  .b-para { font-size:33px; line-height:1.42; color:var(--muted); text-wrap:pretty; }

  /* ---- stat ---- */
  .b-stat { padding:8px 0; }
