  /* ---- quote ---- */
  .b-quote { border-left:10px solid var(--fg); padding:6px 0 6px 36px; }
  .quote-text { font-size:36px; line-height:1.4; color:var(--fg); }
  .quote-attr { font-size:26px; color:var(--muted); margin-top:18px; }

