// ---------------------------------------------------------------------------
const DARK_TYPES = ['hook', 'cta', 'payoff'];   // use the negative (white) logo
const SWIPE_HINT = ['hook', 'stakes'];          // slides that must earn the swipe
const DENSE_AT = 5;                             // weight at which we top-align

function logoMarkup(slideType, g) {
  const src = DARK_TYPES.includes(slideType)
    ? (g.LOGO_URL_NEGATIVE || '')
    : (g.LOGO_URL || '');
  return src
    ? `<img class="logo-img" src="${esc(src)}" alt="TU/e">`
    : `<span class="logo-ph">TU/e logo</span>`;
}

function renderSlide(s, total, g) {
  const blocks = Array.isArray(s.blocks) ? s.blocks : [];
  const weight = slideWeight(blocks, s.headline, s.slide_type);
  const hasChip = !!s.kicker;
  const cls = [
    'slide',
    'slide--' + esc(s.slide_type),
    weight >= DENSE_AT ? 'slide--dense' : '',
  ].filter(Boolean).join(' ');

  return `
  <div class="${cls}">
    <div class="top">
      <span class="progress">${s.slide_number}/${total}</span>
    </div>
    <div class="content${hasChip ? '' : ' content--nochip'}">
      <div class="fit">
        ${hasChip ? `<span class="chip">${esc(s.kicker)}</span>` : ''}
        <h1 class="headline">${headlineHtml(s.headline, s.accent)}</h1>
        <div class="blocks">${blocks.map(renderBlock).join('')}</div>
      </div>
    </div>
    <div class="footer">
      <span class="handle">${esc(g.FACULTY_NAME)}</span>
      <div class="footer-right">
        ${SWIPE_HINT.includes(s.slide_type) ? `<span class="swipe">Swipe &rarr;</span>` : ''}
        <div class="logo">${logoMarkup(s.slide_type, g)}</div>
      </div>
    </div>
  </div>`;
}

function buildCarouselHtml(parent, g) {
  const total = parent.total_slides || parent.slides.length;
  const slidesHtml = parent.slides.map((s) => renderSlide(s, total, g)).join('\n');
  return `<!doctype html>
<html><head><meta charset="utf-8"><style>${stylesheet(g)}</style></head>
<body>
${slidesHtml}
</body></html>`;
}

// ============================================================================
//  n8n GLUE  —  everything below this line is n8n-specific.
// ============================================================================

const parent = $json;
const g = $('Globals').first().json;
const html = buildCarouselHtml(parent, g);

return [{
  json: {
    // slides are stripped from _parent so the payload stays small; the poster
    // and the sheet only ever need the scalar fields.
    _parent: { ...parent, slides: undefined },
    slides: parent.slides.map((s) => ({
      slide_number: s.slide_number,
      slide_type: s.slide_type,
      density: slideWeight(s.blocks, s.headline, s.slide_type),
    })),
    total_slides: parent.total_slides || parent.slides.length,
    html,
  },
}];

// Carries the renderer's `fits` array and the new `urls` array through so the
// approval gate sees which slides shrank, and the sheet gets public image URLs.

const resp = $json;
const build = $('Build Carousel HTML').first().json;
const meta = build.slides || [];
const images = resp.images || [];
const fits = Array.isArray(resp.fits) ? resp.fits : [];
const urls = Array.isArray(resp.urls) ? resp.urls : [];

if (images.length !== meta.length) {
  throw new Error(`Renderer returned ${images.length} images but expected ${meta.length}`);
}
if (urls.length !== meta.length) {
  throw new Error(
    `Renderer returned ${urls.length} urls but expected ${meta.length}. ` +
    `Is PUBLIC_BASE_URL set on the carousel-renderer container?`
  );
}

const parent = { ...build._parent, _fits: fits };

const out = [];
for (let i = 0; i < meta.length; i++) {
  const m = meta[i];
  const img = images[i];
  const b64 = typeof img === 'string' ? img : (img.image_base64 || img.base64 || img.data);
  if (!b64) throw new Error('No image data for slide ' + m.slide_number);
  const buffer = Buffer.from(b64, 'base64');
  const binaryData = await this.helpers.prepareBinaryData(
    buffer, `slide_${m.slide_number}.jpg`, 'image/jpeg'
  );
  out.push({
    json: {
      _parent: parent,
      slide_number: m.slide_number,
      slide_type: m.slide_type,
      density: m.density,
      fit: fits[i] ?? 1,
      public_url: urls[i],
    },
    binary: { data: binaryData },
  });
}
return out;

// Pairs each Drive upload response back to its slide by position.
// Runs in "Run Once for All Items" mode (the default) — returns one item per slide.

const prevAll = $('Split Render Output').all();
const items = $input.all();

if (items.length !== prevAll.length) {
  throw new Error(
    `Drive returned ${items.length} items but Split Render Output had ${prevAll.length}`
  );
}

return items.map((item, i) => {
  const prev = prevAll[i].json;
  const driveResp = item.json;
  if (!driveResp.id) {
    throw new Error('Drive upload returned no file id for slide ' + prev.slide_number);
  }
  return {
    json: {
      _parent: prev._parent,
      slide_number: prev.slide_number,
      slide_type: prev.slide_type,
      drive_file_id: driveResp.id,
      drive_view_link: `https://drive.google.com/file/d/${driveResp.id}/view`,
      public_url: prev.public_url,
    },
  };
});

// slide_urls now holds the publicly-fetchable renderer URLs (what Instagram
// needs). The Drive backup links stay in notes for the human review pass.

const arr = ($json.slide_number || []).map((n, i) => ({
  slide_number: n,
  slide_type: $json.slide_type[i],
  drive_file_id: $json.drive_file_id[i],
  drive_view_link: $json.drive_view_link[i],
  public_url: $json.public_url[i],
}));
arr.sort((a, b) => a.slide_number - b.slide_number);

const parent = $('Capture Slide Ref').first().json._parent;

const warnings = parent._warnings || [];
const fits = Array.isArray(parent._fits) ? parent._fits : [];
const shrunk = fits
  .map((f, i) => (f && f < 1 ? `${i + 1} (${Math.round(f * 100)}%)` : null))
  .filter(Boolean);

const notes = [
  `Layout: ${parent._block_summary || 'n/a'}`,
  shrunk.length
    ? `Auto-fit shrank ${shrunk.length} slide(s): ${shrunk.join(', ')}`
    : (fits.length ? 'Auto-fit: all slides fitted at full size' : 'Auto-fit: not reported'),
  warnings.length ? `Auto-repaired (${warnings.length}): ${warnings.join('; ')}` : 'Auto-repaired: none',
  '',
  'Drive backups:',
  ...arr.map((s) => `${s.slide_number}. ${s.drive_view_link}`),
].join('\n');

return [{
  json: {
    drive_file_id: parent.drive_file_id,
    title: parent.title,
    content_hook: parent.content_hook,
    content_brief: parent.content_brief,
    slide_urls: arr.map((s) => s.public_url).join('\n'),
    caption: parent.caption,
    hashtags: (parent.hashtags || []).join(' '),
    generated_at: new Date().toISOString(),
    status: 'generated',
    notes,
  },
}];
